INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000029',1,'APPROVED','PUBLISHED',
'{"objectives":["Name basic political and government concepts in Hindi at A1","Use X का नेतृत्व करना for leadership","Talk about voting and democracy"],"explanation":{"intro":"Politics and government vocabulary covers democratic institutions, leaders, and basic civic concepts in Hindi at A1.","culturalNote":"राजनीति और सरकार — Politics and Government: राजनीति (rajneeti) = politics (Sanskrit: raja = king + niti = policy). सरकार (sarkar) = government (Persian). लोकतंत्र (loktantra) = democracy (Sanskrit: lok = people + tantra = system). संसद (sansad) = parliament. चुनाव (chunaav) = election. मतदान (matdaan) = voting (mat = vote + daan = giving). नेता (neta) = leader/politician. प्रधानमंत्री (Pradhanmantri) = Prime Minister. राष्ट्रपति (Rashtrapati) = President. मुख्यमंत्री (Mukhyamantri) = Chief Minister. India: world''s largest democracy — 900 million+ eligible voters. Lok Sabha (lower house), Rajya Sabha (upper house). 543 constituencies. EC (Election Commission — independent — conducts elections). Key: भारत एक लोकतांत्रिक गणराज्य है (India is a democratic republic). First past the post electoral system. Coalition governments common. EVM (Electronic Voting Machine)."},"examples":[{"hindi":"भारत में हर पाँच साल में चुनाव होते हैं।","transliteration":"Bharat mein har paanch saal mein chunaav hote hain.","english":"In India elections take place every five years."},{"hindi":"नागरिकों को मतदान करना चाहिए।","transliteration":"Nagrikon ko matdaan karna chahiye.","english":"Citizens should vote."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about basic political and democratic concepts in Hindi."}}',
'{"items":[{"word":"राजनीति","translation":"politics","transliteration":"rajneeti","pronunciation":"raj-NEE-ti","example":"राजनीति में भाग।"},{"word":"सरकार","translation":"government","transliteration":"sarkar","pronunciation":"sar-KAR","example":"सरकार की नीति।"},{"word":"लोकतंत्र","translation":"democracy","transliteration":"loktantra","pronunciation":"lok-TAN-tra","example":"भारतीय लोकतंत्र।"},{"word":"चुनाव","translation":"election","transliteration":"chunaav","pronunciation":"chu-NAAV","example":"चुनाव लड़ना।"},{"word":"मतदान","translation":"voting","transliteration":"matdaan","pronunciation":"mat-DAAN","example":"मतदान करना।"},{"word":"नागरिक","translation":"citizen","transliteration":"naagrik","pronunciation":"NAA-grik","example":"भारतीय नागरिक।"}]}',
'{"title":"हर X में Y होता/होती है — Every X, Y happens (हर = every, habitual pattern)","pattern":"हर X में Y होता/होती है = Every X there is Y. हर = every (invariant — does not inflect). Examples: हर साल में = every year. हर पाँच साल में = every five years. हर सोमवार को = every Monday. Y होता है = Y happens habitually (masculine Y), होती है (feminine Y).","explanation":"हर (har) = every, each (invariant adjective — precedes noun, no agreement needed). हर + time noun: हर दिन (every day), हर सप्ताह (every week), हर साल (every year), हर बार (every time). हर X में = every X (with में for time periods). हर साल में → less formal: हर साल. Habitual: होता है/होती है. Every + time → habitual truth about recurrence.","examples":[{"sentence":"हर साल मानसून आता है।","transliteration":"Har saal monsoon aata hai.","translation":"Every year the monsoon comes."},{"sentence":"हर सोमवार को बाज़ार लगता है।","transliteration":"Har somvaar ko baazaar lagta hai.","translation":"Every Monday the market is held."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"लोकतंत्र means?","options":["democracy","government","parliament","politics"],"correctAnswer":"democracy"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In India elections take place every five years.","options":["भारत में हर पाँच साल में चुनाव होते हैं।","भारत में हर चार साल में चुनाव होते हैं।","भारत में हर पाँच साल में मतदान होता है।","भारत में हर पाँच साल में संसद होती है।"],"correctAnswer":"भारत में हर पाँच साल में चुनाव होते हैं।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"हर साल मानसून ___ है।","options":["आता","आती","आते","आतीं"],"correctAnswer":"आता"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Citizens should vote.","wordBankItems":["नागरिकों","को","मतदान","करना","चाहिए","।"],"correctAnswer":"नागरिकों को मतदान करना चाहिए ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"चुनाव means?","options":["election","government","leader","vote"],"correctAnswer":"election"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000002a',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about technology and science in Hindi at A1","Use X का उपयोग करना for using technology","Describe technology in daily life"],"explanation":{"intro":"Technology and science vocabulary covers digital technology, scientific concepts, and how to describe their role in daily life in Hindi at A1.","culturalNote":"तकनीक और विज्ञान — Technology and Science: तकनीक (takneek) = technology (from Arabic tiqniya). विज्ञान (vigyan) = science (Sanskrit: vi = apart + jnana = knowledge). कंप्यूटर (computer). मोबाइल (mobile). इंटरनेट (internet). उपयोग (upyog) = use/usage. ऐप (app). India: IT sector — Bengaluru = ''Silicon Valley of India.'' TCS, Infosys, Wipro — global IT companies. ISRO (Indian Space Research Organisation) — Chandrayaan (Moon mission), Mangalyaan (Mars mission). IIT (Indian Institutes of Technology) — world-class engineering education. Digital India initiative (Narendra Modi 2015 — digitise government services). Aadhaar (आधार = base/foundation — biometric ID system — 1.3 billion registered). UPI payments. COVID-19 CoWIN vaccination platform — managed 2 billion doses. IT professionals from India work globally — large diaspora in Silicon Valley."},"examples":[{"hindi":"आजकल सभी काम कंप्यूटर से होते हैं।","transliteration":"Aajkal sabhi kaam computer se hote hain.","english":"Nowadays all work is done by computer."},{"hindi":"भारत का अंतरिक्ष कार्यक्रम बहुत उन्नत है।","transliteration":"Bharat ka antriksh karyakram bahut unnat hai.","english":"India''s space programme is very advanced."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about technology and science in Hindi."}}',
'{"items":[{"word":"तकनीक","translation":"technology","transliteration":"takneek","pronunciation":"tak-NEEK","example":"नई तकनीक।"},{"word":"विज्ञान","translation":"science","transliteration":"vigyan","pronunciation":"vig-YAAN","example":"विज्ञान पढ़ना।"},{"word":"उपयोग","translation":"use/usage","transliteration":"upyog","pronunciation":"up-YOG","example":"उपयोग करना।"},{"word":"अंतरिक्ष","translation":"space/outer space","transliteration":"antriksh","pronunciation":"an-TRIKSH","example":"अंतरिक्ष यात्रा।"},{"word":"आजकल","translation":"nowadays","transliteration":"aajkal","pronunciation":"aaj-KAL","example":"आजकल तकनीक।"},{"word":"उन्नत","translation":"advanced/developed","transliteration":"unnat","pronunciation":"UN-nat","example":"उन्नत तकनीक।"}]}',
'{"title":"X से Y होना — Y is/happens by/through X (passive-like causation)","pattern":"X से Y होना = Y happens/is done through X. से = by/through (instrument/means postposition). आजकल काम कंप्यूटर से होता है = Nowadays work is done by computer. Passive-like construction: the action (Y) + होना = to happen. X से = by means of X. No agent marker (से marks the instrument, not the agent in this pattern).","explanation":"Causation/means with से: X से Y होना = Y is done/happens through X. Passive-like construction without a direct agent: काम होता है (work gets done — intransitive होना). Computer se hote hain = are done by computer (literally: happen through computer). Similar: बस से जाना (to go by bus), हाथ से बनाना (to make by hand). Compare: X ने Y किया (X did Y — active past with agent marker ने — ergative construction).","examples":[{"sentence":"यह काम मशीन से होता है।","transliteration":"Yah kaam masheen se hota hai.","translation":"This work is done by machine."},{"sentence":"बातचीत फ़ोन से होती है।","transliteration":"Baatcheet phone se hoti hai.","translation":"Conversation happens by phone."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"विज्ञान means?","options":["science","technology","knowledge","research"],"correctAnswer":"science"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Nowadays all work is done by computer.","options":["आजकल सभी काम कंप्यूटर से होते हैं।","आजकल कुछ काम कंप्यूटर से होते हैं।","पहले सभी काम कंप्यूटर से होते थे।","आजकल सभी काम मशीन से होते हैं।"],"correctAnswer":"आजकल सभी काम कंप्यूटर से होते हैं।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"यह काम मशीन ___ होता है।","options":["से","में","पर","को"],"correctAnswer":"से"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Conversation happens by phone.","wordBankItems":["बातचीत","फ़ोन","से","होती","है","।"],"correctAnswer":"बातचीत फ़ोन से होती है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"आजकल means?","options":["nowadays","earlier","sometimes","always"],"correctAnswer":"nowadays"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000002b',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about Indian history at A1","Use past tense था/थी/थे","Describe historical events simply"],"explanation":{"intro":"History vocabulary covers key moments in Indian history and how to use the simple past tense था/थी/थे in Hindi at A1.","culturalNote":"इतिहास — History: इतिहास (itihaas) = history (Sanskrit: iti = thus + ha = certainly + aasa = it was — ''thus indeed it was''). Key history: Indus Valley Civilisation (सिंधु घाटी सभ्यता = Sindhu Ghati Sabhyata — 3300-1300 BCE — Harappa, Mohenjo-daro). Maurya Empire (मौर्य साम्राज्य — Ashoka = great Buddhist emperor — 268-232 BCE). Mughal Empire (मुगल साम्राज्य — Akbar, Shah Jahan, Aurangzeb — 1526-1857). British Raj (ब्रिटिश राज — 1858-1947). Independence (स्वतंत्रता — 1947 August 15). Mahatma Gandhi (महात्मा गाँधी — father of nation — Non-violence — Satyagraha). Jawaharlal Nehru (Tryst with Destiny speech). Partition (विभाजन — India/Pakistan 1947). Republic Day 1950. Key: था/थी/थे (tha/thi/the = was/were — past of होना). था (masculine singular), थी (feminine singular), थे (masculine plural or respectful singular)."},"examples":[{"hindi":"गाँधीजी एक महान नेता थे।","transliteration":"Gandhiji ek mahan neta the.","english":"Gandhiji was a great leader."},{"hindi":"भारत 1947 में स्वतंत्र हुआ।","transliteration":"Bharat 1947 mein swatantra hua.","english":"India became independent in 1947."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about Indian history at A1 using past tense था/थी/थे."}}',
'{"items":[{"word":"इतिहास","translation":"history","transliteration":"itihaas","pronunciation":"i-ti-HAAS","example":"भारत का इतिहास।"},{"word":"स्वतंत्रता","translation":"independence/freedom","transliteration":"swatantrata","pronunciation":"swa-TAN-tra-ta","example":"स्वतंत्रता दिवस।"},{"word":"महान","translation":"great","transliteration":"mahaan","pronunciation":"ma-HAAN","example":"महान नेता।"},{"word":"था/थी/थे","translation":"was/were","transliteration":"tha/thi/the","pronunciation":"tha/thi/the","example":"वह महान था।"},{"word":"साम्राज्य","translation":"empire","transliteration":"samarajya","pronunciation":"saam-RAAJ-ya","example":"मुगल साम्राज्य।"},{"word":"स्वतंत्र","translation":"independent/free","transliteration":"swatantra","pronunciation":"swa-TAN-tra","example":"स्वतंत्र देश।"}]}',
'{"title":"X था/थी/थे — X was/were (past of होना)","pattern":"था = was (masculine singular). थी = was (feminine singular). थे = were (masculine plural / respectful singular). Agreement with subject gender and number. गाँधीजी महान नेता थे (Gandhi was a great leader — थे for respectful singular). भारत स्वतंत्र था (India was independent — था for masculine noun भारत). नदी गहरी थी (the river was deep — थी for feminine noun नदी).","explanation":"Past tense of होना (to be): था (tha) = was, masculine singular. थी (thi) = was, feminine singular. थे (the) = were, masculine plural OR respectful singular (like थे for respected individuals). थीं (theen) = were, feminine plural. Used in simple past: X + predicate + था/थी/थे. Used in past continuous (with raha/rahi): X + verb + raha tha (was doing — masculine). Compound: पढ़ रहा था (was reading — masculine), पढ़ रही थी (was reading — feminine).","examples":[{"sentence":"वह एक अच्छी शिक्षिका थीं।","transliteration":"Vah ek acchi shikshika theen.","translation":"She was a good teacher."},{"sentence":"हम कल घर पर थे।","transliteration":"Hum kal ghar par the.","translation":"We were at home yesterday."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"इतिहास means?","options":["history","geography","science","economics"],"correctAnswer":"history"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Gandhiji was a great leader.","options":["गाँधीजी एक महान नेता थे।","नेहरूजी एक महान नेता थे।","गाँधीजी एक महान नेता हैं।","गाँधीजी एक अच्छे नेता थे।"],"correctAnswer":"गाँधीजी एक महान नेता थे।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"हम कल घर पर ___ ।","options":["थे","था","थी","हैं"],"correctAnswer":"थे"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: India became independent in 1947.","wordBankItems":["भारत","1947","में","स्वतंत्र","हुआ","।"],"correctAnswer":"भारत 1947 में स्वतंत्र हुआ ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"महान means?","options":["great","good","important","famous"],"correctAnswer":"great"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000002c',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about children and education in Hindi at A1","Use X पढ़ाना for teaching","Describe educational experiences"],"explanation":{"intro":"Children and education vocabulary covers school stages, learning, and teaching in Hindi at A1.","culturalNote":"बच्चे और शिक्षा — Children and Education: बच्चा/बच्ची (bachcha/bachchi = child — male/female). पढ़ाई (padhaai = studies/education). सीखना (seekhna = to learn). पढ़ाना (padhaana = to teach). विद्यालय (vidyaalay = school — Sanskrit). प्राथमिक विद्यालय (praathamik vidyaalay = primary school). माध्यमिक विद्यालय (madyamik = secondary school). महाविद्यालय (mahaavidyaalay = college). विश्वविद्यालय (vishwavidyaalay = university — vishwa = world + vidya = knowledge + aalaya = place). परीक्षा (pariksha = exam). India has 1.4 million schools, 260 million students. RTE (Right to Education Act 2009 — free, compulsory education 6-14). Anganwadi (early childhood centres). NEET (National Eligibility cum Entrance Test — medicine), JEE (engineering). Coaching centres — Kota, Rajasthan — famous for IIT/NEET coaching — ''coaching capital of India.'' Drop-out rate still an issue especially for girls in rural areas. Mid-day meal scheme (पोषण — nutrition for school attendance)."},"examples":[{"hindi":"मेरी बेटी अभी पाँचवीं कक्षा में पढ़ती है।","transliteration":"Meri beti abhi paanchvi kaksha mein padhti hai.","english":"My daughter is currently studying in the fifth class."},{"hindi":"शिक्षा हर बच्चे का अधिकार है।","transliteration":"Shiksha har bachche ka adhikar hai.","english":"Education is the right of every child."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about children and education in Hindi."}}',
'{"items":[{"word":"बच्चा/बच्ची","translation":"child (m/f)","transliteration":"bachcha/bachchi","pronunciation":"BACH-cha/BACH-chi","example":"मेरा बच्चा।"},{"word":"पढ़ाई","translation":"studies/education","transliteration":"padhaai","pronunciation":"pad-HAAI","example":"पढ़ाई करना।"},{"word":"सीखना","translation":"to learn","transliteration":"seekhna","pronunciation":"SEEKH-na","example":"हिंदी सीखना।"},{"word":"परीक्षा","translation":"exam","transliteration":"pariksha","pronunciation":"pa-RICK-sha","example":"परीक्षा देना।"},{"word":"अधिकार","translation":"right","transliteration":"adhikaar","pronunciation":"adhi-KAAR","example":"शिक्षा का अधिकार।"},{"word":"विश्वविद्यालय","translation":"university","transliteration":"vishwavidyaalay","pronunciation":"vish-wa-vid-YAA-lay","example":"विश्वविद्यालय में।"}]}',
'{"title":"X हर Y का अधिकार है — X is the right of every Y","pattern":"X हर Y का अधिकार है = X is the right of every Y. अधिकार (adhikaar) = right (masculine noun). का agrees with अधिकार (masculine). हर Y का = every Y''s (हर = every; का = possessive). X = the right/entitlement. Pattern commonly used for rights statements in Indian civic discourse.","explanation":"Rights expressions: X का अधिकार = right to X. Y का अधिकार = Y''s right. Combining: हर बच्चे का अधिकार = every child''s right. हर (har) = every — triggers oblique: हर बच्चे (every child — oblique because preceding का). Oblique of बच्चा (masculine -a noun) → बच्चे. Rights discourse: भारतीय संविधान (Indian Constitution) guarantees fundamental rights (मौलिक अधिकार = maulik adhikar) — Art. 19-22.","examples":[{"sentence":"स्वास्थ्य सेवा सभी का अधिकार है।","transliteration":"Swasthya seva sabhi ka adhikaar hai.","translation":"Healthcare is the right of all."},{"sentence":"मतदान हर नागरिक का अधिकार है।","transliteration":"Matdaan har naagrik ka adhikaar hai.","translation":"Voting is the right of every citizen."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"परीक्षा means?","options":["exam","class","subject","result"],"correctAnswer":"exam"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Education is the right of every child.","options":["शिक्षा हर बच्चे का अधिकार है।","शिक्षा हर नागरिक का अधिकार है।","शिक्षा बच्चे का अधिकार है।","स्वास्थ्य हर बच्चे का अधिकार है।"],"correctAnswer":"शिक्षा हर बच्चे का अधिकार है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मतदान हर नागरिक का ___ है।","options":["अधिकार","काम","कर्तव्य","अवसर"],"correctAnswer":"अधिकार"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: My daughter is currently studying in the fifth class.","wordBankItems":["मेरी","बेटी","अभी","पाँचवीं","कक्षा","में","पढ़ती","है","।"],"correctAnswer":"मेरी बेटी अभी पाँचवीं कक्षा में पढ़ती है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"सीखना means?","options":["to learn","to teach","to study","to read"],"correctAnswer":"to learn"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000002d',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about business and the economy in Hindi at A1","Use X बेचना/ख़रीदना for buying and selling","Describe basic economic activities"],"explanation":{"intro":"Business and economy vocabulary covers trade, commerce, and basic economic concepts in Hindi at A1.","culturalNote":"व्यापार और अर्थव्यवस्था — Business and Economy: व्यापार (vyaapaar) = trade/business (Sanskrit). अर्थव्यवस्था (arthavyavastha) = economy (artha = wealth/purpose + vyavastha = arrangement). बेचना (bechna) = to sell. ख़रीदना (kharidna) = to buy. उत्पाद (utpad) = product. निर्यात (niryaat) = export. आयात (aayaat) = import. उद्योग (udyog) = industry. India: 5th largest economy (GDP). Key sectors: IT (Bengaluru/Hyderabad), textiles (Gujarat, Maharashtra), agriculture (60% dependent), pharmaceuticals (India = ''pharmacy of the world''). Key companies: Reliance, Tata Group, Infosys, HDFC. FDI (Foreign Direct Investment). Make in India (''मेक इन इंडिया'' — Modi 2014 — manufacturing initiative). Start-up India (भारत में 100 unicorns — स्टार्टअप = startup). Key markets: Mumbai (financial capital), Delhi-NCR (government/telecom), Bengaluru (tech)."},"examples":[{"hindi":"भारत विश्व में सॉफ़्टवेयर का निर्यात करता है।","transliteration":"Bharat vishwa mein software ka niryaat karta hai.","english":"India exports software to the world."},{"hindi":"छोटे व्यापारी बाज़ार में सामान बेचते हैं।","transliteration":"Chhote vyaapari baazaar mein saamaan bechte hain.","english":"Small traders sell goods in the market."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about business and the economy in Hindi."}}',
'{"items":[{"word":"व्यापार","translation":"trade/business","transliteration":"vyaapaar","pronunciation":"vyaa-PAAR","example":"व्यापार करना।"},{"word":"बेचना","translation":"to sell","transliteration":"bechna","pronunciation":"BECH-na","example":"सामान बेचना।"},{"word":"ख़रीदना","translation":"to buy","transliteration":"kharidna","pronunciation":"kha-REE-dna","example":"सामान ख़रीदना।"},{"word":"निर्यात","translation":"export","transliteration":"niryaat","pronunciation":"nir-YAAT","example":"निर्यात करना।"},{"word":"उद्योग","translation":"industry","transliteration":"udyog","pronunciation":"UD-yog","example":"IT उद्योग।"},{"word":"सामान","translation":"goods/things","transliteration":"saamaan","pronunciation":"SAA-maan","example":"सामान बेचना।"}]}',
'{"title":"X, Y को Z करता है — X does Z to Y (transitive verb with indirect object)","pattern":"X Y को Z करता है = X does Z to Y. को after Y marks the indirect object (the recipient/target of the action). Applies when there is a direct object (Z) and a direction/target (Y को). भारत विश्व को सॉफ़्टवेयर निर्यात करता है = India exports software to the world. को marks the destination of the export.","explanation":"को (ko) as indirect object marker: marks recipient, destination, target of an action. Verbs with indirect objects: देना (to give — to whom), बेचना (to sell — to whom), बताना (to tell — to whom), भेजना (to send — to whom). दुकानदार ग्राहक को सामान देता है = The shopkeeper gives goods to the customer. Pattern: Agent + Indirect-obj-को + Direct-obj + Verb. Note: को also marks the dative (मुझे, तुम्हें) and is used for other functions — context determines which use.","examples":[{"sentence":"वह दुकानदार हमें सस्ते दाम पर सामान बेचता है।","transliteration":"Vah dukaandaar hamein saste daam par saamaan bechta hai.","translation":"That shopkeeper sells goods to us at cheap prices."},{"sentence":"भारत दूसरे देशों को दवाएँ निर्यात करता है।","transliteration":"Bharat doosre deshon ko dawaayen niryaat karta hai.","translation":"India exports medicines to other countries."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"व्यापार means?","options":["trade/business","industry","economy","market"],"correctAnswer":"trade/business"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"India exports software to the world.","options":["भारत विश्व में सॉफ़्टवेयर का निर्यात करता है।","भारत सॉफ़्टवेयर आयात करता है।","विश्व भारत को सॉफ़्टवेयर निर्यात करता है।","भारत दवाएँ निर्यात करता है।"],"correctAnswer":"भारत विश्व में सॉफ़्टवेयर का निर्यात करता है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"छोटे व्यापारी बाज़ार में सामान ___ हैं।","options":["बेचते","ख़रीदते","देते","लेते"],"correctAnswer":"बेचते"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: India exports medicines to other countries.","wordBankItems":["भारत","दूसरे","देशों","को","दवाएँ","निर्यात","करता","है","।"],"correctAnswer":"भारत दूसरे देशों को दवाएँ निर्यात करता है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"बेचना means?","options":["to sell","to buy","to trade","to exchange"],"correctAnswer":"to sell"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000002e',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about religion and faith in Hindi at A1","Use X में विश्वास करना for belief","Describe religious practices"],"explanation":{"intro":"Religion and faith vocabulary covers major Indian religions and how to talk about spiritual practices in Hindi at A1.","culturalNote":"धर्म और आस्था — Religion and Faith: धर्म (dharm) = religion/duty/righteousness (Sanskrit — multiple meanings: cosmic order, personal duty, religion). आस्था (aastha) = faith/belief. पूजा (pooja) = Hindu worship/prayer. नमाज़ (namaaz) = Islamic prayer. गुरुद्वारा (Gurudwara) = Sikh temple. मंदिर (mandir) = Hindu temple. मस्जिद (masjid) = mosque. गिरजाघर (girjaaghar) = church. विश्वास (vishwaas) = faith/belief/trust. India: world''s most religiously diverse major country. Hinduism (80%), Islam (14%), Christianity (2.3%), Sikhism (1.7%), Buddhism, Jainism, Zoroastrianism (Parsis), Judaism. Dharma (धर्म) has no direct English equivalent — cosmic order, duty, righteous conduct, religion all in one. India is the birthplace of Hinduism, Buddhism, Jainism and Sikhism. Religious festivals are national holidays. Secular constitution but deeply religious society. Vasudhaiva Kutumbakam (वसुधैव कुटुम्बकम् = the world is one family — Sanskrit proverb — India''s motto for G20 presidency 2023)."},"examples":[{"hindi":"भारत में अनेक धर्म और त्योहार हैं।","transliteration":"Bharat mein anek dharm aur tyohaar hain.","english":"In India there are many religions and festivals."},{"hindi":"मंदिर में लोग पूजा करते हैं।","transliteration":"Mandir mein log pooja karte hain.","english":"People worship/pray in the temple."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about religion and faith in Hindi and name major places of worship."}}',
'{"items":[{"word":"धर्म","translation":"religion/duty","transliteration":"dharm","pronunciation":"dharm","example":"धर्म और संस्कृति।"},{"word":"पूजा","translation":"worship/prayer","transliteration":"pooja","pronunciation":"POO-ja","example":"पूजा करना।"},{"word":"मंदिर","translation":"temple","transliteration":"mandir","pronunciation":"MAN-dir","example":"मंदिर जाना।"},{"word":"विश्वास","translation":"faith/belief/trust","transliteration":"vishwaas","pronunciation":"vish-WAAS","example":"विश्वास करना।"},{"word":"अनेक","translation":"many/various","transliteration":"anek","pronunciation":"a-NEK","example":"अनेक धर्म।"},{"word":"लोग","translation":"people","transliteration":"log","pronunciation":"log","example":"लोग पूजा करते हैं।"}]}',
'{"title":"X में Y करते हैं — People do Y in X (general truth about a place)","pattern":"X में Y करते हैं = (People) do Y in X. Habitual 3rd person plural: करते हैं. लोग X में Y करते हैं = People do Y in X. X = location (temple, mosque, etc.). Y = activity. The subject लोग (people) is often omitted — implied general ''they.''","explanation":"General truth construction: location + में + activity + करते/करती हैं. Implied subject ''people'' or ''they'': मंदिर में पूजा होती है (worship happens in temples — impersonal होना). मंदिर में लोग पूजा करते हैं (people worship in temples — explicit subject). The impersonal होना (लोग X करते हैं vs. X होती है) are both common ways to express habitual general truths in Hindi. Plural verb agreement: करते हैं (3rd person pl. habitual).","examples":[{"sentence":"मस्जिद में नमाज़ पढ़ी जाती है।","transliteration":"Masjid mein namaaz padhi jaati hai.","translation":"Prayer is read in the mosque."},{"sentence":"गुरुद्वारे में लंगर होता है।","transliteration":"Gurudware mein langar hota hai.","translation":"Community meals are held in the Gurudwara."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"मंदिर means?","options":["temple","mosque","church","shrine"],"correctAnswer":"temple"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In India there are many religions and festivals.","options":["भारत में अनेक धर्म और त्योहार हैं।","भारत में दो धर्म और त्योहार हैं।","भारत में अनेक भाषाएँ और त्योहार हैं।","विश्व में अनेक धर्म और त्योहार हैं।"],"correctAnswer":"भारत में अनेक धर्म और त्योहार हैं।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मंदिर में लोग पूजा ___ हैं।","options":["करते","करता","करती","होते"],"correctAnswer":"करते"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Community meals are held in the Gurudwara.","wordBankItems":["गुरुद्वारे","में","लंगर","होता","है","।"],"correctAnswer":"गुरुद्वारे में लंगर होता है ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"विश्वास means?","options":["faith/belief/trust","religion","prayer","duty"],"correctAnswer":"faith/belief/trust"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-00000000002f',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about marriage and family life in Hindi at A1","Use शादी करना for getting married","Describe family events"],"explanation":{"intro":"Marriage and family vocabulary covers weddings, family events, and relationships in Hindi at A1.","culturalNote":"शादी और परिवार — Marriage and Family: शादी/विवाह (shaadi/vivaah) = marriage/wedding. शादी करना (shaadi karna = to get married). दुल्हा/दुल्हन (dulha/dulhan = groom/bride). सास/ससुर (saas/sasur = mother-in-law/father-in-law). बहू/दामाद (bahu/daamaad = daughter-in-law/son-in-law). संयुक्त परिवार (sanyukt parivaar = joint family). नाता/रिश्ता (naata/rishta = relationship/relation). Indian weddings: elaborate multi-day events. Arranged marriage (arranged marriage) vs. love marriage — both common. Dowry (दहेज = dahez — illegal but persists). Mangalsutra (sacred necklace — Hindu married women). बाराती (baraati = wedding procession). Mehndi (मेहंदी = henna ceremony). Pheras (फेरे = 7 circumambulations around fire — Hindu wedding vows). Court marriage (legal civil ceremony). Interfaith marriages increasing in cities. India''s fertility rate has declined to 2.0 (near replacement level). Nuclear family (एकल परिवार = ekal parivaar) increasingly common in cities."},"examples":[{"hindi":"मेरे भाई की शादी अगले महीने है।","transliteration":"Mere bhai ki shaadi agle mahine hai.","english":"My brother''s wedding is next month."},{"hindi":"भारतीय शादियाँ बहुत रंगारंग होती हैं।","transliteration":"Bhartiya shaadiyaan bahut rangaarang hoti hain.","english":"Indian weddings are very colourful."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about marriage and family events in Hindi."}}',
'{"items":[{"word":"शादी","translation":"wedding/marriage","transliteration":"shaadi","pronunciation":"SHAA-dee","example":"शादी करना।"},{"word":"दुल्हा/दुल्हन","translation":"groom/bride","transliteration":"dulha/dulhan","pronunciation":"DUL-ha/DUL-han","example":"दुल्हा और दुल्हन।"},{"word":"अगले महीने","translation":"next month","transliteration":"agle mahine","pronunciation":"AG-le ma-HEE-ne","example":"अगले महीने शादी।"},{"word":"रंगारंग","translation":"colourful","transliteration":"rangaarang","pronunciation":"ran-GAA-rang","example":"रंगारंग त्योहार।"},{"word":"संयुक्त परिवार","translation":"joint family","transliteration":"sanyukt parivaar","pronunciation":"san-YUKT pa-ri-VAAR","example":"संयुक्त परिवार में।"},{"word":"रिश्ता","translation":"relationship/relation","transliteration":"rishta","pronunciation":"RISH-ta","example":"पारिवारिक रिश्ता।"}]}',
'{"title":"मेरे X की Y Z में है — My X''s Y is in Z (chained possessives)","pattern":"मेरे X की Y = My X''s Y. Chained possession: mera → mere (oblique before की) + X + की + Y. मेरे भाई की शादी = my brother''s wedding (mere = oblique of mera before की; bhai = brother; ki agrees with shaadi = feminine; shaadi = wedding). Multiple levels of possession follow the same pattern: A के B की C = A''s B''s C.","explanation":"Chained possessives: each level requires the correct possessive marker and oblique. मेरे (oblique of मेरा — before की) + भाई + की (feminine because शादी is feminine) + शादी. Key: the possessive marker (का/की/के) agrees with the FINAL possessed noun (शादी = feminine → की). Previous nouns in the chain go to oblique: मेरे (not मेरा), भाई stays (already oblique form = same as direct for consonant-ending nouns). More complex: मेरी बहन के पति का नाम = my sister''s husband''s name (name is masculine → का).","examples":[{"sentence":"मेरी दोस्त की बेटी बहुत होशियार है।","transliteration":"Meri dost ki beti bahut hoshiyaar hai.","translation":"My friend''s daughter is very clever."},{"sentence":"आपके भाई की नौकरी कहाँ है?","transliteration":"Aapke bhai ki naukri kahaan hai?","translation":"Where is your brother''s job?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"शादी means?","options":["wedding/marriage","family","celebration","ceremony"],"correctAnswer":"wedding/marriage"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My brother''s wedding is next month.","options":["मेरे भाई की शादी अगले महीने है।","मेरी बहन की शादी अगले महीने है।","मेरे भाई की शादी इस महीने है।","मेरे भाई का विवाह अगले साल है।"],"correctAnswer":"मेरे भाई की शादी अगले महीने है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"मेरी दोस्त ___ बेटी बहुत होशियार है।","options":["की","का","के","को"],"correctAnswer":"की"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Indian weddings are very colourful.","wordBankItems":["भारतीय","शादियाँ","बहुत","रंगारंग","होती","हैं","।"],"correctAnswer":"भारतीय शादियाँ बहुत रंगारंग होती हैं ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"रिश्ता means?","options":["relationship/relation","family","marriage","bond"],"correctAnswer":"relationship/relation"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000030',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about cooking in Hindi at A1","Use पकाना and बनाना for cooking","Name cooking methods and utensils"],"explanation":{"intro":"Cooking vocabulary covers kitchen actions, utensils, and how to describe the cooking process in Hindi at A1.","culturalNote":"भोजन पकाना — Cooking: पकाना (pakaana) = to cook. बनाना (banaana) = to make/prepare. रसोई (rasoi) = kitchen. तवा (tawa) = flat griddle for rotis. कड़ाही (kadaahi) = wok/deep pan. पतीला (pateela) = pot. चाकू (chaaku) = knife. मसाले (masale) = spices. तलना (talna) = to fry. उबालना (ubaalna) = to boil. भूनना (bhunna) = to roast/sauté. लोई (loi) = dough ball. बेलना (belna) = to roll (dough). Key Indian cooking: रोटी बनाना (roti banaana = making rotis — daily ritual in most North Indian homes). दाल पकाना (daal pakaana = cooking lentils — basic daily staple). चावल पकाना (chaawal pakaana = cooking rice). तड़का लगाना (tadka lagaana = tempering spices — adding spices to hot oil — fundamental technique). Key masala: garam masala, haldi (turmeric), jeera (cumin), rai (mustard seeds). India''s spice complexity is extraordinary — cooking varies dramatically by region, caste, religion."},"examples":[{"hindi":"माँ हर रोज़ खाना बनाती है।","transliteration":"Maan har roz khaana banaati hai.","english":"Mum makes food every day."},{"hindi":"दाल को आधे घंटे तक उबालें।","transliteration":"Daal ko aadhe ghante tak ubaalein.","english":"Boil the lentils for half an hour."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about cooking in Hindi and name basic cooking methods."}}',
'{"items":[{"word":"पकाना","translation":"to cook","transliteration":"pakaana","pronunciation":"pa-KAA-na","example":"खाना पकाना।"},{"word":"बनाना","translation":"to make/prepare","transliteration":"banaana","pronunciation":"ba-NAA-na","example":"रोटी बनाना।"},{"word":"तलना","translation":"to fry","transliteration":"talna","pronunciation":"TAL-na","example":"समोसा तलना।"},{"word":"उबालना","translation":"to boil","transliteration":"ubaalna","pronunciation":"u-BAAL-na","example":"दाल उबालना।"},{"word":"मसाले","translation":"spices","transliteration":"masale","pronunciation":"ma-SA-le","example":"मसाले डालना।"},{"word":"तक","translation":"until/up to","transliteration":"tak","pronunciation":"tak","example":"आधे घंटे तक।"}]}',
'{"title":"X को Y तक Z करें — do Z to X for/until Y (तक = until/for, polite imperative करें)","pattern":"X को Y तक Z करें = Please do Z to X for/until Y. को = marks the object (dative/accusative). तक = until/for (duration or endpoint). करें = polite imperative of करना (करना → करें — formal plural/polite). Alternative polite: कीजिए. Recipe instructions often use करें or कीजिए.","explanation":"तक (tak) = until, up to, for. Time: आधे घंटे तक = for half an hour. Place: दिल्ली तक = up to Delhi. Degree: जितना हो सके तक = to the extent possible. Recipe imperatives: करें (kare = do — formal imperative plural/polite), डालें (dalen = add — polite), मिलाएँ (milaen = mix — polite), छोड़ें (chhoden = leave — polite), हटाएँ (hataen = remove — polite). These are the standard recipe verb forms in Hindi.","examples":[{"sentence":"प्याज़ को सुनहरा होने तक भूनें।","transliteration":"Pyaaz ko sunehra hone tak bhoonaen.","translation":"Fry the onions until golden."},{"sentence":"चावल को पंद्रह मिनट तक पकाएँ।","transliteration":"Chaawal ko pandrah minute tak pakaen.","translation":"Cook the rice for fifteen minutes."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"उबालना means?","options":["to boil","to fry","to roast","to steam"],"correctAnswer":"to boil"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Mum makes food every day.","options":["माँ हर रोज़ खाना बनाती है।","माँ कभी-कभी खाना बनाती है।","माँ हर रोज़ खाना पकाती है।","पिताजी हर रोज़ खाना बनाते हैं।"],"correctAnswer":"माँ हर रोज़ खाना बनाती है।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"चावल को पंद्रह मिनट ___ पकाएँ।","options":["तक","से","में","पर"],"correctAnswer":"तक"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Fry the onions until golden.","wordBankItems":["प्याज़","को","सुनहरा","होने","तक","भूनें","।"],"correctAnswer":"प्याज़ को सुनहरा होने तक भूनें ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"मसाले means?","options":["spices","vegetables","grains","herbs"],"correctAnswer":"spices"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000031',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about volunteering and community service in Hindi at A1","Use X की मदद करना for helping","Describe social contribution"],"explanation":{"intro":"Volunteering and society vocabulary covers community service, helping others, and social responsibility in Hindi at A1.","culturalNote":"स्वयंसेवा और समाज — Volunteering and Society: स्वयंसेवा (swayamseva) = volunteering (swayam = self + seva = service). मदद (madad) = help. सेवा (seva) = service. समाज (samaaj) = society. NGO (एनजीओ). सामाजिक कार्य (samaajik kaarya = social work). दान (daan) = donation/charity (from Sanskrit — same root as ''donation''). ग़रीब (garib = poor person). ज़रूरतमंद (zarooratmand = needy). Key: सेवा भाव (seva bhaav = spirit of service — deeply valued in Indian culture). Langar (लंगर) = free community kitchen — Sikh institution — feeds thousands daily without distinction. Gandhi''s concept: सर्वोदय (sarvodaya = welfare of all). Social workers: Anna Hazare, Medha Patkar. NGOs: Pratham (education), Smile Foundation, CRY. बसेरा (base/shelter). Anna Bhag (food distribution). Cultural: India has a long tradition of seva — from Sikh langar to temple prasad distribution to community wells (baawdi). चंदा (chanda = subscription/contribution to a common cause — festival, community project)."},"examples":[{"hindi":"हमें ग़रीब लोगों की मदद करनी चाहिए।","transliteration":"Hamein garib logon ki madad karni chahiye.","english":"We should help poor people."},{"hindi":"स्वयंसेवकों ने बाढ़ पीड़ितों की सहायता की।","transliteration":"Swayamsevakon ne baadh peediton ki sahaayata ki.","english":"Volunteers helped the flood victims."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can talk about volunteering and social responsibility in Hindi."}}',
'{"items":[{"word":"स्वयंसेवा","translation":"volunteering/selfless service","transliteration":"swayamseva","pronunciation":"swa-yam-SE-va","example":"स्वयंसेवा करना।"},{"word":"मदद","translation":"help","transliteration":"madad","pronunciation":"ma-DAD","example":"मदद करना।"},{"word":"सेवा","translation":"service","transliteration":"seva","pronunciation":"SE-va","example":"सेवा भाव।"},{"word":"ग़रीब","translation":"poor","transliteration":"garib","pronunciation":"ga-REEB","example":"ग़रीब लोग।"},{"word":"ज़रूरतमंद","translation":"needy","transliteration":"zarooratmand","pronunciation":"za-ROO-rat-mand","example":"ज़रूरतमंद की मदद।"},{"word":"समाज","translation":"society","transliteration":"samaaj","pronunciation":"sa-MAAJ","example":"समाज के लिए।"}]}',
'{"title":"X ने Y की Z की — X did Z of Y (past tense with ने — ergative)","pattern":"X ने Y की Z की = X did Z of Y (past tense with ने — ergative construction). ने is the agent marker in past tense for transitive verbs. स्वयंसेवकों ने पीड़ितों की सहायता की = volunteers helped the victims. ने follows the subject in past tense (ergative: used when the verb is transitive and perfective past).","explanation":"Ergative construction in Hindi past tense: when a transitive verb is in perfective past, the subject takes ने (ne). स्वयंसेवकों (plural oblique of स्वयंसेवक) + ने (agent marker) + बाढ़ पीड़ितों की (flood victims'') + सहायता (help) + की (did — feminine because सहायता is feminine). Key: past transitive = subject + ने + object + verb. The verb agrees with the OBJECT in perfective past (not the subject — ''split ergativity''). सहायता की (help + ki = did-help — ki because सहायता is feminine). If no object: verb agrees with subject.","examples":[{"sentence":"माँ ने खाना बनाया।","transliteration":"Maan ne khaana banaaya.","translation":"Mum made food."},{"sentence":"बच्चों ने गाना गाया।","transliteration":"Bachhon ne gaana gaaya.","translation":"The children sang a song."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"मदद means?","options":["help","service","charity","support"],"correctAnswer":"help"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"We should help poor people.","options":["हमें ग़रीब लोगों की मदद करनी चाहिए।","हमें ज़रूरतमंद लोगों की मदद करनी चाहिए।","मुझे ग़रीब लोगों की मदद करनी चाहिए।","हमें ग़रीब लोगों को मदद करनी चाहिए।"],"correctAnswer":"हमें ग़रीब लोगों की मदद करनी चाहिए।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"माँ ___ खाना बनाया।","options":["ने","को","से","का"],"correctAnswer":"ने"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The children sang a song.","wordBankItems":["बच्चों","ने","गाना","गाया","।"],"correctAnswer":"बच्चों ने गाना गाया ।"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"समाज means?","options":["society","community","group","nation"],"correctAnswer":"society"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('cc000000-0000-0000-0000-000000000032',1,'APPROVED','PUBLISHED',
'{"objectives":["Review and consolidate Hindi A1 learning","Use a range of A1 structures","Talk about Indian culture and daily life comprehensively"],"explanation":{"intro":"Hindi A1 completion lesson reviews key structures and vocabulary from across the A1 level, with a focus on daily life and Indian cultural context.","culturalNote":"A1 समापन — A1 Review: Completing Hindi A1 means you can: greet people, introduce yourself, describe your family, talk about daily routines, express likes and dislikes, navigate markets, ask directions, discuss weather and seasons, name festivals, and talk about basic civic and cultural topics. Key grammar structures mastered: SOV word order; मैं X हूँ (I am X); मुझे X पसंद है (I like X); मुझे X चाहिए (I want/need X); मुझे X करना है (I need to do X); हमें X करना चाहिए (we should do X); मेरे X में Y हैं (in my X there are Y); X बजे Y करना (to do Y at X o''clock); habitual present (ता/ती/ते हूँ/है/हैं); continuous present (-रहा/रही/रहे हूँ/है/हैं); future (करूँगा/करूँगी); simple past था/थी/थे; past transitive ने. Cultural highlights: India''s incredible diversity of language, religion, food, geography. You are ready to move to A2 where everyday conversations become more complex and narrative begins."},"examples":[{"hindi":"मुझे भारत बहुत पसंद है — यहाँ के रंग, खाना, संगीत और लोग सभी अद्भुत हैं।","transliteration":"Mujhe Bharat bahut pasand hai — yahaan ke rang, khaana, sangeet aur log sabhi adbhut hain.","english":"I like India very much — its colours, food, music and people are all wonderful."},{"hindi":"मैंने बहुत कुछ सीखा — अब मैं हिंदी में बात कर सकता हूँ।","transliteration":"Maine bahut kuch seekha — ab main Hindi mein baat kar sakta hoon.","english":"I have learned a lot — now I can speak in Hindi."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":20,"canDo":"I can hold basic conversations in Hindi across a wide range of everyday topics — I have completed Hindi A1."}}',
'{"items":[{"word":"अद्भुत","translation":"wonderful/amazing","transliteration":"adbhut","pronunciation":"ad-BHUT","example":"अद्भुत देश।"},{"word":"सभी","translation":"all/everyone","transliteration":"sabhi","pronunciation":"SAB-hi","example":"सभी लोग।"},{"word":"अब","translation":"now","transliteration":"ab","pronunciation":"ab","example":"अब बोल सकता हूँ।"},{"word":"सकना","translation":"can/to be able to","transliteration":"sakna","pronunciation":"SAK-na","example":"बोल सकता हूँ।"},{"word":"बहुत कुछ","translation":"a lot/much","transliteration":"bahut kuch","pronunciation":"ba-HUT kuch","example":"बहुत कुछ सीखा।"},{"word":"यहाँ","translation":"here","transliteration":"yahaan","pronunciation":"ya-HAAN","example":"यहाँ अच्छा है।"}]}',
'{"title":"मैं X कर सकता/सकती हूँ — I can do X (सकना = can, modal verb)","pattern":"मैं X कर सकता हूँ (male) / सकती हूँ (female) = I can do X. सकना = can/be able to (modal). Verb stem + सकना: stem + सकता/सकती/सकते है/हैं/हो/हूँ. बोल सकता हूँ (I can speak — male), बोल सकती हूँ (female). Agreement of सकना matches subject gender. Negative: X नहीं कर सकता (cannot do X).","explanation":"Modal verb सकना (sakna) = can, be able to. Construction: verb stem + सकता/सकती (agreement form of sakna) + हूँ/है/हैं. बोलना → बोल + सकता हूँ = I can speak. जाना → जा + सकता हूँ = I can go. समझना → समझ + सकता हूँ = I can understand. All modal constructions in Hindi are compound: main verb stem + modal verb (fully conjugated). Other modals: पड़ना (padna = must/have to), चाहना (chahna = want to). सकना is the most common ''can'' modal.","examples":[{"sentence":"वह तीन भाषाएँ बोल सकती है।","transliteration":"Vah teen bhashayen bol sakti hai.","translation":"She can speak three languages."},{"sentence":"क्या आप कल आ सकते हैं?","transliteration":"Kya aap kal aa sakte hain?","translation":"Can you come tomorrow?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"अद्भुत means?","options":["wonderful/amazing","beautiful","good","great"],"correctAnswer":"wonderful/amazing"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I like India very much — its colours, food, music and people are all wonderful.","options":["मुझे भारत बहुत पसंद है — यहाँ के रंग, खाना, संगीत और लोग सभी अद्भुत हैं।","मुझे भारत पसंद है — यहाँ का खाना और संगीत अद्भुत है।","मुझे भारत बहुत पसंद है — सभी देश अद्भुत हैं।","भारत बहुत अद्भुत देश है — यहाँ सभी कुछ अच्छा है।"],"correctAnswer":"मुझे भारत बहुत पसंद है — यहाँ के रंग, खाना, संगीत और लोग सभी अद्भुत हैं।"},{"id":"ex3","type":"FILL_IN_BLANK","question":"वह तीन भाषाएँ बोल ___ है।","options":["सकती","सकता","सकते","सकना"],"correctAnswer":"सकती"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Can you come tomorrow?","wordBankItems":["क्या","आप","कल","आ","सकते","हैं","?"],"correctAnswer":"क्या आप कल आ सकते हैं ?"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"सकना means?","options":["can/be able to","want to","need to","should"],"correctAnswer":"can/be able to"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

